import { DataTable, Then, When } from '@wdio/cucumber-framework';
import movementsCasesFilterContainerScreen from '@screenobjects/payment/movements-cases-filter-container.screen.ts';

When(/^el usuario consulta todos sus movimientos en contenedor movimientos casuisticas filtro$/, async (dataTable: DataTable) => {
    const filtroValues = dataTable.hashes().map((row) => row["filtro"]);
    await movementsCasesFilterContainerScreen.userViewAllMovementsEnMovementsCasesFilterContainer(filtroValues);
});

Then(/^se muestran los movimientos esperados$/, async () => {
    await movementsCasesFilterContainerScreen.showMovementsExpected();
});

