import { $ } from '@wdio/globals';
import BaseScreen from '@screenobjects/commons/base.screen.ts';
import LocatorProvider from '@common/locators/locator-provider.js';
import { TypeLocator } from '@common/enums/locator-type.enum.js';
import Locators from '@locators/payment/movements-cases-filter-container.locator.json' with { type: 'json' };
import { getTimeoutFromEnv } from '@common/utils/env/environment-config.js';

const timeout: number = getTimeoutFromEnv();

class MovementsCasesFilterContainerScreen extends BaseScreen {

    public get showMovementsButton() {
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, Locators["movementsCasesFilterContainerIos"].showMovementsButton,
            TypeLocator.ANDROID, Locators["movementsCasesFilterContainerAndroid"].showMovementsButton
        );
        return $(locator);
    }

    public get seeAllMovementsButton() {
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, Locators["movementsCasesFilterContainerIos"].seeAllMovementsButton,
            TypeLocator.ID, Locators["movementsCasesFilterContainerAndroid"].seeAllMovementsButton
        );
        return $(locator);
    }

    public get filterMovementsButton() {
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, Locators["movementsCasesFilterContainerIos"].filterMovementsButton,
            TypeLocator.ID, Locators["movementsCasesFilterContainerAndroid"].filterMovementsButton
        );
        return $(locator);
    }

    public filterOnlyToday(filtro: string) {
        const iosValue = Locators["movementsCasesFilterContainerIos"].filterOnlyToday.replace('{filtro}', filtro);
        const androidValue = Locators["movementsCasesFilterContainerAndroid"].filterOnlyToday.replace('{filtro}', filtro);
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, iosValue,
            TypeLocator.ANDROID, androidValue
        );
        return $(locator);
    }

    public get validateMovementsTitleContainer() {
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, Locators["movementsCasesFilterContainerIos"].validateMovementsTitleContainer,
            TypeLocator.XPATH, Locators["movementsCasesFilterContainerAndroid"].validateMovementsTitleContainer
        );
        return $(locator);
    }

    public async userViewAllMovementsEnMovementsCasesFilterContainer(filtroValues: string[]): Promise<void> {
        await this.uiHelper.waitForElementExistByLocator(this.showMovementsButton, true);
        await this.showMovementsButton.click();
        await this.gestureHelper.verticalScrollingToEnd();
        await this.gestureHelper.verticalScrollingToEnd();
        await this.uiHelper.waitForElementExistByLocator(this.seeAllMovementsButton, true);
        await this.seeAllMovementsButton.click();
        for (const filtroValue of filtroValues) {
            await this.uiHelper.waitForElementExistByLocator(this.filterMovementsButton, true);
            await this.filterMovementsButton.click();
            await this.uiHelper.waitForElementExistByLocator(this.filterOnlyToday(filtroValue), true);
            await this.filterOnlyToday(filtroValue).click();
        }
    }

    public async showMovementsExpected(): Promise<void> {
        await this.uiHelper.waitForElementDisplayedAndExpect(this.validateMovementsTitleContainer, timeout, 'The expected element was not displayed');
    }
}

export default new MovementsCasesFilterContainerScreen();

